import {
  type DynamicScheme,
  Hct,
  SchemeContent,
  SchemeExpressive,
  SchemeFidelity,
  SchemeFruitSalad,
  SchemeMonochrome,
  SchemeNeutral,
  SchemeRainbow,
  SchemeTonalSpot,
  SchemeVibrant,
  argbFromHex,
  hexFromArgb,
} from "@material/material-color-utilities";

/**
 * Color tokens.
 *
 * Provide a seed color and Expressive derives five tonal palettes and every
 * semantic color role from it, using Google's Material color algorithm
 * (HCT color space, 2025 / Expressive spec).
 */

export const schemeVariants = {
  "tonal-spot": SchemeTonalSpot,
  expressive: SchemeExpressive,
  vibrant: SchemeVibrant,
  neutral: SchemeNeutral,
  monochrome: SchemeMonochrome,
  fidelity: SchemeFidelity,
  content: SchemeContent,
  rainbow: SchemeRainbow,
  "fruit-salad": SchemeFruitSalad,
} as const;

export type SchemeVariant = keyof typeof schemeVariants;

export const colorRoles = [
  "primary",
  "onPrimary",
  "primaryContainer",
  "onPrimaryContainer",
  "primaryFixed",
  "primaryFixedDim",
  "onPrimaryFixed",
  "onPrimaryFixedVariant",
  "inversePrimary",
  "secondary",
  "onSecondary",
  "secondaryContainer",
  "onSecondaryContainer",
  "secondaryFixed",
  "secondaryFixedDim",
  "onSecondaryFixed",
  "onSecondaryFixedVariant",
  "tertiary",
  "onTertiary",
  "tertiaryContainer",
  "onTertiaryContainer",
  "tertiaryFixed",
  "tertiaryFixedDim",
  "onTertiaryFixed",
  "onTertiaryFixedVariant",
  "error",
  "onError",
  "errorContainer",
  "onErrorContainer",
  "background",
  "onBackground",
  "surface",
  "onSurface",
  "surfaceVariant",
  "onSurfaceVariant",
  "surfaceDim",
  "surfaceBright",
  "surfaceContainerLowest",
  "surfaceContainerLow",
  "surfaceContainer",
  "surfaceContainerHigh",
  "surfaceContainerHighest",
  "inverseSurface",
  "inverseOnSurface",
  "outline",
  "outlineVariant",
  "shadow",
  "scrim",
  "surfaceTint",
] as const;

export type ColorRole = (typeof colorRoles)[number];
export type ColorRoles = Record<ColorRole, string>;

export const paletteNames = ["primary", "secondary", "tertiary", "neutral", "neutralVariant", "error"] as const;
export type PaletteName = (typeof paletteNames)[number];

export const paletteTones = [0, 4, 6, 10, 12, 17, 20, 22, 24, 30, 40, 50, 60, 70, 80, 87, 90, 92, 94, 95, 96, 98, 99, 100] as const;
export type TonalPalette = Record<(typeof paletteTones)[number], string>;

export interface ColorScheme {
  seed: string;
  variant: SchemeVariant;
  contrast: number;
  light: ColorRoles;
  dark: ColorRoles;
  palettes: Record<PaletteName, TonalPalette>;
}

export interface ColorOptions {
  /** Seed color as a hex string, e.g. `#6750A4`. */
  seed: string;
  variant?: SchemeVariant;
  /** -1 (reduced) … 0 (standard) … 1 (high contrast). */
  contrast?: number;
  /** Override individual roles after generation. */
  overrides?: { light?: Partial<ColorRoles>; dark?: Partial<ColorRoles> };
}

function createDynamicScheme(seed: string, variant: SchemeVariant, isDark: boolean, contrast: number): DynamicScheme {
  const Scheme = schemeVariants[variant];
  return new Scheme(Hct.fromInt(argbFromHex(seed)), isDark, contrast, "2025");
}

function rolesFrom(scheme: DynamicScheme): ColorRoles {
  const roles = {} as ColorRoles;
  for (const role of colorRoles) {
    roles[role] = hexFromArgb(scheme[role]);
  }
  return roles;
}

export function generateScheme({ seed, variant = "expressive", contrast = 0, overrides }: ColorOptions): ColorScheme {
  const light = createDynamicScheme(seed, variant, false, contrast);
  const dark = createDynamicScheme(seed, variant, true, contrast);

  const palettes = {} as Record<PaletteName, TonalPalette>;
  for (const name of paletteNames) {
    const palette = light[`${name}Palette`];
    const tones = {} as TonalPalette;
    for (const tone of paletteTones) {
      tones[tone] = hexFromArgb(palette.tone(tone));
    }
    palettes[name] = tones;
  }

  return {
    seed,
    variant,
    contrast,
    light: { ...rolesFrom(light), ...overrides?.light },
    dark: { ...rolesFrom(dark), ...overrides?.dark },
    palettes,
  };
}

/** `surfaceContainerHigh` → `surface-container-high` */
export function toKebab(name: string): string {
  return name.replace(/([a-z0-9])([A-Z])/g, "$1-$2").toLowerCase();
}

/**
 * Typography tokens.
 *
 * Semantic roles instead of font sizes. Any variable font works: families are
 * resolved through `--ex-font-brand` (display/headline/title) and
 * `--ex-font-plain` (body/label), which `createTheme` fills from `fonts`.
 */

export interface TypeStyle {
  family: "brand" | "plain";
  /** Font size in px. */
  size: number;
  /** Line height in px. */
  lineHeight: number;
  weight: number;
  /** Letter spacing in px. */
  tracking: number;
  /** Extra variable-font axes, e.g. `{ opsz: 36, wdth: 100 }`. */
  axes?: Record<string, number>;
}

export const typeRoles = [
  "display-large",
  "display-medium",
  "display-small",
  "headline-large",
  "headline-medium",
  "headline-small",
  "title-large",
  "title-medium",
  "title-small",
  "body-large",
  "body-medium",
  "body-small",
  "label-large",
  "label-medium",
  "label-small",
] as const;

export type TypeRole = (typeof typeRoles)[number];
export type TypeScale = Record<TypeRole | `${TypeRole}-emphasized`, TypeStyle>;

export interface Fonts {
  brand: string;
  plain: string;
}

export const defaultFonts: Fonts = {
  brand: `"Roboto Flex", ui-sans-serif, system-ui, sans-serif`,
  plain: `"Roboto Flex", ui-sans-serif, system-ui, sans-serif`,
};

const baseline: Record<TypeRole, TypeStyle> = {
  "display-large": { family: "brand", size: 57, lineHeight: 64, weight: 400, tracking: -0.25 },
  "display-medium": { family: "brand", size: 45, lineHeight: 52, weight: 400, tracking: 0 },
  "display-small": { family: "brand", size: 36, lineHeight: 44, weight: 400, tracking: 0 },
  "headline-large": { family: "brand", size: 32, lineHeight: 40, weight: 400, tracking: 0 },
  "headline-medium": { family: "brand", size: 28, lineHeight: 36, weight: 400, tracking: 0 },
  "headline-small": { family: "brand", size: 24, lineHeight: 32, weight: 400, tracking: 0 },
  "title-large": { family: "brand", size: 22, lineHeight: 28, weight: 400, tracking: 0 },
  "title-medium": { family: "plain", size: 16, lineHeight: 24, weight: 500, tracking: 0.15 },
  "title-small": { family: "plain", size: 14, lineHeight: 20, weight: 500, tracking: 0.1 },
  "body-large": { family: "plain", size: 16, lineHeight: 24, weight: 400, tracking: 0.5 },
  "body-medium": { family: "plain", size: 14, lineHeight: 20, weight: 400, tracking: 0.25 },
  "body-small": { family: "plain", size: 12, lineHeight: 16, weight: 400, tracking: 0.4 },
  "label-large": { family: "plain", size: 14, lineHeight: 20, weight: 500, tracking: 0.1 },
  "label-medium": { family: "plain", size: 12, lineHeight: 16, weight: 500, tracking: 0.5 },
  "label-small": { family: "plain", size: 11, lineHeight: 16, weight: 500, tracking: 0.5 },
};

/** M3 Expressive "emphasized" styles: same metrics, heavier weight. */
function emphasize(style: TypeStyle): TypeStyle {
  return { ...style, weight: style.weight >= 500 ? 700 : 500 };
}

export const defaultTypeScale = Object.fromEntries(
  typeRoles.flatMap((role) => [
    [role, baseline[role]],
    [`${role}-emphasized`, emphasize(baseline[role])],
  ]),
) as TypeScale;

/**
 * Shape tokens.
 *
 * A corner scale plus named presets. Components consume `shape="…"` props
 * that resolve to these tokens, never raw radius values.
 */

export const cornerScale = {
  none: 0,
  "extra-small": 4,
  small: 8,
  medium: 12,
  large: 16,
  "large-increased": 20,
  "extra-large": 28,
  "extra-large-increased": 32,
  "extra-extra-large": 48,
  full: 9999,
} as const;

export type Corner = keyof typeof cornerScale;
export type CornerScale = Record<Corner, number>;

/**
 * Corner styles. `squircle` and `cut` rely on CSS `corner-shape`
 * (progressive enhancement: browsers without support render `round`).
 */
export type CornerStyle = "round" | "squircle" | "cut";

export interface ShapePreset {
  corner: Corner;
  style: CornerStyle;
}

export const shapePresets = {
  rounded: { corner: "medium", style: "round" },
  pill: { corner: "full", style: "round" },
  circular: { corner: "full", style: "round" },
  squircle: { corner: "extra-large", style: "squircle" },
  cut: { corner: "small", style: "cut" },
  small: { corner: "small", style: "round" },
  medium: { corner: "medium", style: "round" },
  large: { corner: "large", style: "round" },
  "extra-large": { corner: "extra-large", style: "round" },
} as const satisfies Record<string, ShapePreset>;

export type ShapeName = keyof typeof shapePresets;

export interface ShapeTokens {
  corners: CornerScale;
  presets: Record<string, ShapePreset>;
}

export const defaultShape: ShapeTokens = { corners: { ...cornerScale }, presets: { ...shapePresets } };

/**
 * Elevation tokens.
 *
 * Material expresses depth primarily through surface tone; shadows are a
 * secondary cue. Each level pairs a shadow with a surface container role.
 */

export const elevationLevels = [0, 1, 2, 3, 4, 5] as const;
export type ElevationLevel = (typeof elevationLevels)[number];

export interface ElevationToken {
  shadow: string;
  surface: "surface" | "surfaceContainerLow" | "surfaceContainer" | "surfaceContainerHigh" | "surfaceContainerHighest";
}

const key = "rgb(from var(--ex-color-shadow) r g b / 0.3)";
const ambient = "rgb(from var(--ex-color-shadow) r g b / 0.15)";

export const defaultElevation: Record<ElevationLevel, ElevationToken> = {
  0: { shadow: "none", surface: "surface" },
  1: { shadow: `0 1px 2px 0 ${key}, 0 1px 3px 1px ${ambient}`, surface: "surfaceContainerLow" },
  2: { shadow: `0 1px 2px 0 ${key}, 0 2px 6px 2px ${ambient}`, surface: "surfaceContainer" },
  3: { shadow: `0 1px 3px 0 ${key}, 0 4px 8px 3px ${ambient}`, surface: "surfaceContainerHigh" },
  4: { shadow: `0 2px 3px 0 ${key}, 0 6px 10px 4px ${ambient}`, surface: "surfaceContainerHigh" },
  5: { shadow: `0 4px 4px 0 ${key}, 0 8px 12px 6px ${ambient}`, surface: "surfaceContainerHighest" },
};

/** Spacing tokens: a 4px-based scale. */

export const defaultSpacing = {
  none: 0,
  "3xs": 2,
  "2xs": 4,
  xs: 8,
  sm: 12,
  md: 16,
  lg: 24,
  xl: 32,
  "2xl": 48,
  "3xl": 64,
} as const;

export type SpacingTokens = Record<string, number>;

/**
 * Interaction tokens.
 *
 * Shared by every component through the state layer, ripple and focus ring,
 * so hover/press/focus feel identical regardless of who wrote the component.
 */

export interface InteractionTokens {
  stateLayer: { hover: number; focus: number; pressed: number; dragged: number };
  disabled: { content: number; container: number };
  focusRing: { width: number; offset: number; color: string };
  ripple: { duration: number; opacity: number };
}

export const defaultInteraction: InteractionTokens = {
  stateLayer: { hover: 0.08, focus: 0.1, pressed: 0.1, dragged: 0.16 },
  disabled: { content: 0.38, container: 0.1 },
  focusRing: { width: 3, offset: 2, color: "var(--ex-color-secondary)" },
  ripple: { duration: 450, opacity: 0.12 },
};

/**
 * Theme — combines every token system into one object and serializes it to
 * CSS custom properties. Change the theme, and every component follows.
 */
import { type ColorOptions, type ColorScheme, colorRoles, generateScheme, toKebab } from "./colors";
import { type ElevationLevel, type ElevationToken, defaultElevation, elevationLevels } from "./elevation";
import { type InteractionTokens, defaultInteraction } from "./interaction";
import { type MotionScheme, type MotionTokens, type SpringSpeed, type SpringType, defaultMotion } from "./motion";
import { type ShapeTokens, defaultShape } from "./shape";
import { type SpacingTokens, defaultSpacing } from "./spacing";
import { type Fonts, type TypeScale, defaultFonts, defaultTypeScale } from "./typography";
import { springDuration, springToLinear } from "@/registry/lib/spring";

export interface Theme {
  colors: ColorScheme;
  typography: { fonts: Fonts; scale: TypeScale };
  motion: MotionTokens;
  shape: ShapeTokens;
  spacing: SpacingTokens;
  elevation: Record<ElevationLevel, ElevationToken>;
  interaction: InteractionTokens;
}

type DeepPartial<T> = { [K in keyof T]?: T[K] extends object ? DeepPartial<T[K]> : T[K] };

export interface ThemeOptions {
  colors?: ColorOptions | ColorScheme;
  typography?: DeepPartial<Theme["typography"]>;
  motion?: DeepPartial<MotionTokens>;
  shape?: DeepPartial<ShapeTokens>;
  spacing?: SpacingTokens;
  elevation?: DeepPartial<Theme["elevation"]>;
  interaction?: DeepPartial<InteractionTokens>;
}

export const DEFAULT_SEED = "#6750A4";

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function merge<T>(base: T, override: unknown): T {
  if (!isPlainObject(override)) return base;
  const result: Record<string, unknown> = { ...(base as Record<string, unknown>) };
  for (const [key, value] of Object.entries(override)) {
    if (value === undefined) continue;
    result[key] = isPlainObject(value) && isPlainObject(result[key]) ? merge(result[key], value) : value;
  }
  return result as T;
}

export function createTheme(options: ThemeOptions = {}): Theme {
  const colors =
    options.colors && "light" in options.colors
      ? options.colors
      : generateScheme(options.colors ?? { seed: DEFAULT_SEED });

  return {
    colors,
    typography: merge({ fonts: defaultFonts, scale: defaultTypeScale }, options.typography),
    motion: merge(defaultMotion, options.motion),
    shape: merge(defaultShape, options.shape),
    spacing: options.spacing ?? defaultSpacing,
    elevation: merge(defaultElevation, options.elevation),
    interaction: merge(defaultInteraction, options.interaction),
  };
}

const px = (n: number) => (n === 0 ? "0" : `${n}px`);
/** Percentages work for both `opacity` and Tailwind's `color-mix()` opacity modifiers. */
const pct = (n: number) => `${Math.round(n * 1000) / 10}%`;
const block = (selector: string, vars: Array<[string, string]>) =>
  `${selector} {\n${vars.map(([k, v]) => `  ${k}: ${v};`).join("\n")}\n}`;

const springTypes: SpringType[] = ["spatial", "effects"];
const springSpeeds: SpringSpeed[] = ["fast", "default", "slow"];
const motionSchemes: MotionScheme[] = ["expressive", "standard"];

function motionAliases(scheme: MotionScheme): Array<[string, string]> {
  return springTypes.flatMap((type) =>
    springSpeeds.flatMap((speed): Array<[string, string]> => [
      [`--ex-spring-${type}-${speed}-easing`, `var(--ex-motion-${scheme}-${type}-${speed}-easing)`],
      [`--ex-spring-${type}-${speed}-duration`, `var(--ex-motion-${scheme}-${type}-${speed}-duration)`],
    ]),
  );
}

/** Serialize a theme to CSS custom properties (`--ex-*`). */
export function themeToCss(theme: Theme, { darkSelector = ".dark" } = {}): string {
  const root: Array<[string, string]> = [];

  for (const role of colorRoles) root.push([`--ex-color-${toKebab(role)}`, theme.colors.light[role]]);

  root.push(["--ex-font-brand", theme.typography.fonts.brand], ["--ex-font-plain", theme.typography.fonts.plain]);
  for (const [role, style] of Object.entries(theme.typography.scale)) {
    root.push(
      [`--ex-type-${role}-family`, `var(--ex-font-${style.family})`],
      [`--ex-type-${role}-size`, `${style.size / 16}rem`],
      [`--ex-type-${role}-line-height`, `${style.lineHeight / 16}rem`],
      [`--ex-type-${role}-weight`, String(style.weight)],
      [`--ex-type-${role}-tracking`, px(style.tracking)],
    );
    if (style.axes) {
      const axes = Object.entries(style.axes).map(([axis, value]) => `"${axis}" ${value}`);
      root.push([`--ex-type-${role}-axes`, axes.join(", ")]);
    }
  }

  for (const [name, value] of Object.entries(theme.shape.corners)) root.push([`--ex-shape-corner-${name}`, px(value)]);
  for (const [name, value] of Object.entries(theme.spacing)) root.push([`--ex-space-${name}`, px(value)]);
  for (const level of elevationLevels) root.push([`--ex-elevation-${level}`, theme.elevation[level].shadow]);

  const { stateLayer, disabled, focusRing, ripple } = theme.interaction;
  root.push(
    ["--ex-state-hover", pct(stateLayer.hover)],
    ["--ex-state-focus", pct(stateLayer.focus)],
    ["--ex-state-pressed", pct(stateLayer.pressed)],
    ["--ex-state-dragged", pct(stateLayer.dragged)],
    ["--ex-disabled-content", pct(disabled.content)],
    ["--ex-disabled-container", pct(disabled.container)],
    ["--ex-focus-ring-width", px(focusRing.width)],
    ["--ex-focus-ring-offset", px(focusRing.offset)],
    ["--ex-focus-ring-color", focusRing.color],
    ["--ex-ripple-duration", `${ripple.duration}ms`],
    ["--ex-ripple-opacity", pct(ripple.opacity)],
  );

  for (const scheme of motionSchemes) {
    for (const type of springTypes) {
      for (const speed of springSpeeds) {
        const spring = theme.motion.springs[scheme][type][speed];
        root.push(
          [`--ex-motion-${scheme}-${type}-${speed}-easing`, springToLinear(spring)],
          [`--ex-motion-${scheme}-${type}-${speed}-duration`, `${springDuration(spring)}ms`],
        );
      }
    }
  }
  for (const [name, value] of Object.entries(theme.motion.durations)) root.push([`--ex-duration-${name}`, `${value}ms`]);
  for (const [name, value] of Object.entries(theme.motion.easings)) root.push([`--ex-easing-${name}`, value]);
  root.push(...motionAliases(theme.motion.scheme));

  const dark = colorRoles.map((role): [string, string] => [`--ex-color-${toKebab(role)}`, theme.colors.dark[role]]);
  const noMotion = springTypes.flatMap((type) =>
    springSpeeds.map((speed): [string, string] => [`--ex-spring-${type}-${speed}-duration`, "0ms"]),
  );

  return [
    `/* Generated by Expressive from seed ${theme.colors.seed} (${theme.colors.variant}). */`,
    block(":root", root),
    block(darkSelector, [["color-scheme", "dark"], ...dark]),
    ...motionSchemes.map((scheme) => block(`[data-motion="${scheme}"]`, motionAliases(scheme))),
    block(`[data-motion="none"]`, noMotion),
    `@media (prefers-reduced-motion: reduce) {\n${block(":root, [data-motion]", noMotion)}\n}`,
  ].join("\n\n");
}

/**
 * The static Tailwind v4 mapping from `--ex-*` variables to utilities
 * (`bg-primary`, `text-title-large`, `rounded-shape-large`, `shadow-elevation-2`,
 * `p-ex-md` — spacing is prefixed so it never shadows `max-w-2xl` and friends).
 */
export function themeToTailwind(theme: Theme = createTheme()): string {
  const vars: Array<[string, string]> = [];
  for (const role of colorRoles) vars.push([`--color-${toKebab(role)}`, `var(--ex-color-${toKebab(role)})`]);
  vars.push(["--font-brand", "var(--ex-font-brand)"], ["--font-plain", "var(--ex-font-plain)"]);
  for (const role of Object.keys(theme.typography.scale)) {
    vars.push(
      [`--text-${role}`, `var(--ex-type-${role}-size)`],
      [`--text-${role}--line-height`, `var(--ex-type-${role}-line-height)`],
      [`--text-${role}--letter-spacing`, `var(--ex-type-${role}-tracking)`],
      [`--text-${role}--font-weight`, `var(--ex-type-${role}-weight)`],
    );
  }
  for (const name of Object.keys(theme.shape.corners)) vars.push([`--radius-shape-${name}`, `var(--ex-shape-corner-${name})`]);
  for (const name of Object.keys(theme.spacing)) vars.push([`--spacing-ex-${name}`, `var(--ex-space-${name})`]);
  for (const level of elevationLevels) vars.push([`--shadow-elevation-${level}`, `var(--ex-elevation-${level})`]);
  for (const type of springTypes) {
    for (const speed of springSpeeds) vars.push([`--ease-${type}-${speed}`, `var(--ex-spring-${type}-${speed}-easing)`]);
  }
  return block("@theme inline", vars);
}
